import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours complémentaire de 6e : cours et exercices sur les trois trimestres.
class SixiemeCompletionScreen extends StatelessWidget {
 const SixiemeCompletionScreen({super.key});
 static const _units=<_Unit>[
    _Unit('T1 • Français','Lire un récit et construire une phrase','Un récit présente un cadre, des personnages et des actions. Une phrase verbale contient un verbe conjugué. Je repère le sujet, le verbe et les compléments essentiels.','« Le matin, Afi traverse le marché avec sa sœur. » Sujet : Afi ; verbe : traverse.','Quel est le verbe conjugué ?',['matin','traverse','sœur'],1,'Traverse est le verbe conjugué.'),
    _Unit('T1 • Mathématiques','Nombres entiers, décimaux et calcul','Je compare et range les nombres en utilisant les rangs. Pour additionner ou soustraire des décimaux, j’aligne les virgules. Je vérifie un résultat par estimation.','12,5 + 3,75 = 16,25.','Combien font 8,4 − 2,15 ?',['6,25','6,35','7,25'],0,'8,40 − 2,15 = 6,25.'),
    _Unit('T1 • Anglais','Greetings, classroom and personal information','Je salue, me présente et demande des informations simples. I am, my name is, I live in et how old are you sont des structures fréquentes.','What is your name? — My name is Ama.','Comment demander l’âge ?',['Where are you?','How old are you?','What colour is it?'],1,'How old are you? signifie quel âge as-tu ?'),
    _Unit('T1 • SVT','Êtres vivants et milieux de vie','Un être vivant naît, grandit, se nourrit, se reproduit et meurt. Son milieu fournit des conditions de vie. On observe les caractères pour comparer les organismes.','Une plante verte fabrique sa matière grâce à la lumière, à l’eau et au dioxyde de carbone.','Quel élément est nécessaire à la photosynthèse ?',['La lumière','Le plastique','Le sable sec uniquement'],0,'La lumière fournit l’énergie nécessaire à la photosynthèse.'),
    _Unit('T1 • Physique-Technologie','Matière et mesures','La matière possède une masse et occupe un volume. On mesure la masse avec une balance et le volume avec un récipient gradué ou des méthodes adaptées.','Un litre correspond à 1 000 millilitres.','Quel instrument mesure la masse ?',['Une balance','Un thermomètre','Une règle'],0,'La balance sert à mesurer la masse.'),
    _Unit('T1 • Histoire-Géographie-EMC','Se repérer dans le temps et l’espace','La frise chronologique ordonne les événements. Une carte comporte un titre, une légende et une orientation. En classe, les règles garantissent les droits de chacun.','Sur une frise, les dates sont placées dans l’ordre chronologique.','Quel outil ordonne les événements dans le temps ?',['Une frise chronologique','Un plan de table','Un thermomètre'],0,'La frise chronologique situe les événements dans le temps.'),
    _Unit('T2 • Français','Classes grammaticales et accords','Le nom, le déterminant, l’adjectif, le pronom et le verbe sont des classes grammaticales. Le verbe s’accorde avec son sujet ; le déterminant et l’adjectif s’accordent avec le nom.','« Ces petites maisons blanches sont jolies. » Maisons est féminin pluriel.','Quelle forme est correctement accordée ?',['Les enfant joue','Les enfants jouent','Les enfants joue'],1,'Le sujet pluriel exige jouent.'),
    _Unit('T2 • Mathématiques','Fractions, proportionnalité et géométrie','Une fraction représente des parts égales. Deux grandeurs sont proportionnelles lorsque leur rapport reste constant. Je reconnais les droites parallèles et perpendiculaires.','3/4 de 20 = 15 ; si 1 cahier coûte 200 F, 3 cahiers coûtent 600 F.','Les 2/3 de 18 valent combien ?',['6','12','15'],1,'18 ÷ 3 × 2 = 12.'),
    _Unit('T2 • Anglais','Present simple, routines and questions','Le présent simple exprime les habitudes. Avec he, she ou it, le verbe prend généralement -s. Do et does servent à poser des questions.','She goes to school every day. Do you read?','Complète : He … football on Sundays.',['play','plays','playing'],1,'Avec he, on écrit plays.'),
    _Unit('T2 • SVT','Nutrition et digestion','Les aliments apportent des nutriments et de l’énergie. La digestion transforme les aliments en éléments absorbables. Une alimentation variée et l’eau potable sont importantes.','Les dents coupent et broient les aliments avant leur passage dans le tube digestif.','Où commence la digestion ?',['Dans la bouche','Dans le cœur','Dans les poumons'],0,'La digestion commence dans la bouche.'),
    _Unit('T2 • Physique-Technologie','Mélanges et changements d’état','Un corps pur possède des propriétés caractéristiques. Un mélange associe plusieurs substances. La fusion, la solidification et l’évaporation sont des changements d’état.','La glace fond : elle passe de l’état solide à l’état liquide.','La vaporisation transforme un liquide en…',['solide','gaz','métal'],1,'La vaporisation fait passer à l’état gazeux.'),
    _Unit('T2 • Histoire-Géographie-EMC','Milieux, paysages et activités humaines','Les paysages ruraux et urbains présentent des caractéristiques différentes. Les activités humaines utilisent les ressources et transforment les territoires. Il faut respecter les règles de vie commune.','Un paysage urbain comporte souvent des bâtiments, des routes et des services.','Quelle activité est typiquement agricole ?',['Cultiver du maïs','Construire un pont','Conduire un autobus'],0,'Cultiver est une activité agricole.'),
    _Unit('T3 • Français','Conjugaison et production écrite','Le présent, le passé et le futur situent les actions. Pour écrire un paragraphe, je développe une idée, utilise des connecteurs et relis l’orthographe et la ponctuation.','D’abord, nous préparons le matériel. Ensuite, nous réalisons l’expérience.','Quel connecteur indique la suite ?',['Ensuite','Jamais','Pourtant'],0,'Ensuite marque la progression des actions.'),
    _Unit('T3 • Mathématiques','Périmètres, aires et résolution de problèmes','Le périmètre mesure le contour et l’aire mesure la surface. Pour un rectangle, P = 2(L + l) et A = L × l. Je choisis les unités adaptées.','Rectangle 9 cm × 4 cm : aire 36 cm² ; périmètre 26 cm.','Quelle est l’aire d’un rectangle de 7 cm sur 5 cm ?',['12 cm²','24 cm²','35 cm²'],2,'A = 7 × 5 = 35 cm².'),
    _Unit('T3 • Anglais','Past simple and everyday activities','Le past simple exprime une action terminée. Les verbes réguliers prennent souvent -ed ; certains verbes sont irréguliers. Yesterday indique souvent le passé.','Yesterday, I played football. She went to school.','Quel est le prétérit de « see » ?',['seed','saw','seeing'],1,'See est irrégulier : son prétérit est saw.'),
    _Unit('T3 • SVT','Respiration, reproduction et environnement','La respiration permet les échanges gazeux. Les êtres vivants se reproduisent pour assurer la continuité de leur espèce. La protection des habitats préserve la biodiversité.','Les poumons permettent les échanges entre l’air et le sang chez l’être humain.','Quel gaz l’organisme utilise-t-il pour la respiration ?',['Dioxygène','Hélium','Méthane'],0,'Le dioxygène est utilisé par les cellules.'),
    _Unit('T3 • Physique-Technologie','Électricité simple et sécurité','Un circuit simple comprend un générateur, des conducteurs et un récepteur. Le courant circule lorsque le circuit est fermé. On ne touche jamais aux installations électriques dangereuses.','Une pile, des fils et une lampe forment un circuit simple si les connexions sont correctes.','Quand la lampe s’allume-t-elle ?',['Quand le circuit est fermé','Quand le fil est coupé','Sans générateur'],0,'Un circuit fermé alimenté permet le passage du courant.'),
    _Unit('T3 • Histoire-Géographie-EMC','Citoyenneté, environnement et bilan annuel','La citoyenneté implique le respect des droits, des devoirs et des biens communs. Les gestes écologiques réduisent la pollution et préservent les ressources. Je révise et justifie mes réponses.','Trier les déchets et économiser l’eau sont des gestes responsables.','Quel geste protège l’environnement ?',['Jeter les déchets dans la rivière','Économiser l’eau et trier les déchets','Brûler les plastiques'],1,'Ces gestes limitent la pollution et le gaspillage.'),
 ];
 static int get unitCount=>_units.length;
 static int get lessonCount=>_units.length;
 static List<Exercise> assessmentExercisesForTerm(int term,{String? subjectName}){final prefix='T$term •';final result=<Exercise>[];for(var i=0;i<_units.length;i++){final u=_units[i];if(!u.title.startsWith(prefix))continue;if(subjectName!=null&&!_matches(u.title,subjectName))continue;result.add(Exercise(id:'six_t${term}_u${i}',lessonId:'six_t${term}_u${i}',question:u.question,options:u.options,correctIndex:u.answer,explanation:u.explanation));}return result;}
 static bool _matches(String title,String subject){final t=title.toLowerCase(),s=subject.toLowerCase();if(s.contains('français')||s.contains('francais'))return t.contains('français');if(s.contains('math'))return t.contains('mathématiques');if(s.contains('anglais')||s.contains('english'))return t.contains('anglais');if(s.contains('svt')||s.contains('science'))return t.contains('svt');if(s.contains('physique')||s.contains('technologie'))return t.contains('physique-technologie');if(s.contains('histoire')||s.contains('géographie')||s.contains('education')||s.contains('éducation')||s.contains('emc'))return t.contains('histoire-géographie-emc');return false;}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complément 6ème • Année complète')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('${SixiemeCompletionScreen.unitCount} unités • ${SixiemeCompletionScreen.lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds puis consulte la correction.',style:const TextStyle(fontWeight:FontWeight.w600)))),for(final u in _units)_UnitTile(unit:u)]));
}
class _Unit{final String title,objective,content,example,question;final List<String> options;final int answer;final String explanation;const _Unit(this.title,this.objective,this.content,this.example,this.question,this.options,this.answer,this.explanation);}
class _UnitTile extends StatefulWidget{final _Unit unit;const _UnitTile({required this.unit});@override State<_UnitTile> createState()=>_UnitTileState();}
class _UnitTileState extends State<_UnitTile>{int? choice;bool checked=false;@override Widget build(BuildContext context){final u=widget.unit;return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(u.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(u.objective),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u.content),const SizedBox(height:8),Text('Exemple : ${u.example}',style:const TextStyle(fontStyle:FontStyle.italic)),const SizedBox(height:12),Text(u.question,style:const TextStyle(fontWeight:FontWeight.bold)),for(var i=0;i<u.options.length;i++)RadioListTile<int>(dense:true,contentPadding:EdgeInsets.zero,value:i,groupValue:choice,title:Text(u.options[i]),onChanged:checked?null:(v)=>setState(()=>choice=v)),FilledButton.tonal(onPressed:choice==null?null:()=>setState(()=>checked=true),child:const Text('Vérifier ma réponse')),if(checked)Text('${choice==u.answer?'Bonne réponse ! ':'À revoir. Bonne réponse : ${u.options[u.answer]}. '}${u.explanation}',style:TextStyle(fontWeight:FontWeight.w600,color:choice==u.answer?Colors.green.shade800:Theme.of(context).colorScheme.error)),if(checked)TextButton(onPressed:()=>setState((){choice=null;checked=false;}),child:const Text('Recommencer'))]))]));}}
